-- Phase 6 metrics: per-server samples (bounded retention) + restart schedules.
CREATE TABLE metrics_samples (id TEXT PRIMARY KEY, server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, sampled_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), cpu_percent REAL, memory_usage_bytes INTEGER, memory_limit_bytes INTEGER, restart_count INTEGER NOT NULL DEFAULT -1, players_online INTEGER, latency_ms INTEGER, state TEXT NOT NULL DEFAULT 'unknown');
CREATE INDEX idx_metrics_server_time ON metrics_samples(server_id, sampled_at);
CREATE TABLE scheduled_tasks (id TEXT PRIMARY KEY, server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('restart')), schedule TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'UTC', enabled INTEGER NOT NULL DEFAULT 1, last_run_at TEXT, next_run_at TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')));
